function reviewOwnProfileError(error){return error instanceof TypeError?'个人资料连接或保存未确认，输入保留，请重试或核对服务资料。':error.message}
function reviewOwnProfileSummary(){
 queueMicrotask(()=>reviewReadOwnProfileSummary());
 return `<section class="box" id="own-profile-summary" style="margin:18px 0"><div class="row between"><h2>服务个人资料</h2>${btn('编辑服务个人资料','review-own-profile','ghost')}</div><p class="small muted" role="status" id="own-profile-summary-status">正在读取本人已保存资料…</p><div id="own-profile-summary-content"></div><button id="own-profile-summary-retry" class="ghost" hidden>重新读取资料</button></section>${reviewProfileMethodsSummary()}`;
}
async function reviewReadOwnProfileSummary(force=false){
 const host=document.getElementById('own-profile-summary');if(!host||reviewAuthBusy||reviewAccountConnecting||!S.user?.reviewService||!force&&(host.dataset.reading==='true'||host.dataset.loaded==='true'))return;const generation=String(Number(host.dataset.generation||0)+1);host.dataset.generation=generation;const context=reviewContext(),status=host.querySelector('#own-profile-summary-status'),content=host.querySelector('#own-profile-summary-content'),retry=host.querySelector('#own-profile-summary-retry');host.dataset.reading='true';content.innerHTML='';status.textContent='正在读取本人已保存资料…';retry.hidden=true;
 try{const r=await reviewKnowledgeRequest('/api/review-own-profile',{context});if(!host.isConnected||!reviewContextCurrent(context)||host.dataset.generation!==generation)return;if(r.ownerId!==context.ownerId)throw Error('个人资料回执不一致。');host.dataset.loaded='true';if(!r.profile){status.textContent='尚未保存服务个人资料，原个人介绍和私人实践仍保留。';return}const p=r.profile;status.textContent=p.visibility==='public'?'这份服务个人介绍当前公开。':'这份服务个人介绍仅自己可见。';content.innerHTML=`${p.tagline?`<p>${esc(p.tagline)}</p>`:''}${p.focus?`<p class="small muted">当前关注：${esc(p.focus)}</p>`:''}${p.about?`<details class="saved-notes"><summary>详细介绍</summary><p class="pre">${esc(p.about)}</p></details>`:''}`;
 }catch(e){if(host.isConnected&&reviewContextCurrent(context)&&host.dataset.generation===generation){host.dataset.loaded='false';status.textContent=reviewOwnProfileError(e);retry.hidden=false;retry.onclick=()=>reviewReadOwnProfileSummary(true)}}finally{if(host.dataset.generation===generation)host.dataset.reading='false'}
}
function reviewProfileInput(form){return {tagline:form.elements.namedItem('tagline').value,about:form.elements.namedItem('about').value,focus:form.elements.namedItem('focus').value,visibility:form.elements.namedItem('visibility').value}}
async function reviewOpenOwnProfile(){
 const context=reviewContext();modal('<h2>编辑服务个人资料</h2><p id="own-profile-loading" role="status">正在核对本人资料…</p>','','本人服务资料');const loading=document.getElementById('own-profile-loading');
 try{const r=await reviewKnowledgeRequest('/api/review-own-profile',{context});if(!loading.isConnected||!reviewContextCurrent(context))return;if(r.ownerId!==context.ownerId)throw Error('个人资料回执不一致。');reviewShowOwnProfile(r,context)}catch(e){if(loading.isConnected&&reviewContextCurrent(context)){loading.textContent=reviewOwnProfileError(e);const retry=document.createElement('button');retry.textContent='重新读取本人资料';retry.addEventListener('click',reviewOpenOwnProfile);loading.after(retry)}}
}
function reviewShowOwnProfile(current,context){
 const stored=S.settings.profileDraft,draft=stored?.ownerId===context.ownerId&&stored.data&&typeof stored.baseRevision==='string'?stored:null;let baseRevision=draft?.baseRevision||current.revision;const initial=draft?.data||current.profile||{tagline:'',about:'',focus:'',visibility:'private'};
 modal(`<h2>编辑服务个人资料</h2><p class="small muted">这份资料单独选择公开范围。原个人主页中的介绍、事件和笔记不会自动公开。</p><form id="own-profile-form" class="stack" style="margin-top:16px"><label class="field">一句话介绍<input name="tagline" maxlength="120" value="${esc(initial.tagline)}"></label><label class="field">详细介绍<textarea name="about" maxlength="1600">${esc(initial.about)}</textarea></label><label class="field">当前关注<input name="focus" maxlength="120" value="${esc(initial.focus)}"></label><label class="field">保存范围<select name="visibility"><option value="private" ${initial.visibility==='private'?'selected':''}>仅自己可见</option><option value="public" ${initial.visibility==='public'?'selected':''}>公开个人介绍</option></select></label><label id="own-profile-consent" class="check-row"><input type="checkbox" name="consent">我确认公开以上个人介绍</label><label id="own-profile-withdraw" class="check-row"><input type="checkbox" name="withdrawConsent">我确认将已公开介绍改为私人</label><p id="own-profile-status" role="status">${draft?'已恢复本人未提交的资料输入。':''}</p><button type="submit" class="primary">保存到本人服务账号</button></form><details id="own-profile-current" class="saved-notes"><summary>核对服务当前资料</summary><p id="own-profile-current-text" class="pre small"></p></details><button id="own-profile-refresh" class="ghost">重新读取服务资料并核对</button><button id="own-profile-rebase" class="ghost" hidden>以刚核对的服务版本继续保存我的输入</button>`,'','本人服务资料');
 const f=document.getElementById('own-profile-form'),status=document.getElementById('own-profile-status'),refresh=document.getElementById('own-profile-refresh'),rebase=document.getElementById('own-profile-rebase'),details=document.getElementById('own-profile-current');let busy=false,reviewed=null;
 function showCurrent(r){document.getElementById('own-profile-current-text').textContent=r.profile?`${r.profile.visibility==='public'?'当前公开':'当前私人'}\n${r.profile.tagline}\n${r.profile.about}\n${r.profile.focus}`:'服务尚未保存个人资料。'}showCurrent(current);
 function options(){const pub=f.elements.namedItem('visibility').value==='public';document.getElementById('own-profile-consent').hidden=!pub;f.elements.namedItem('consent').required=pub;const withdraw=current.profile?.visibility==='public'&&!pub;document.getElementById('own-profile-withdraw').hidden=!withdraw;f.elements.namedItem('withdrawConsent').required=withdraw}
 function persist(){if(!f.isConnected||!reviewContextCurrent(context))return;S.settings.profileDraft={ownerId:context.ownerId,baseRevision,data:reviewProfileInput(f)};save()}
 f.addEventListener('input',e=>{if(!f.isConnected||!reviewContextCurrent(context))return;if(!['consent','withdrawConsent'].includes(e.target.name)){f.elements.namedItem('consent').checked=false;f.elements.namedItem('withdrawConsent').checked=false;persist();status.textContent='输入已保留在本人私人行动档案，尚未提交个人资料。'}});f.elements.namedItem('visibility').addEventListener('change',()=>{options();persist()});options();
 refresh.addEventListener('click',async()=>{if(refresh.disabled)return;refresh.disabled=true;try{const r=await reviewKnowledgeRequest('/api/review-own-profile',{context});if(!f.isConnected||!reviewContextCurrent(context))return;if(r.ownerId!==context.ownerId)throw Error('个人资料回执不一致。');reviewed=r;showCurrent(r);details.open=true;rebase.hidden=false;status.textContent='服务当前资料已显示。你的输入保留，请核对后主动选择继续保存。'}catch(e){if(f.isConnected&&reviewContextCurrent(context))status.textContent=reviewOwnProfileError(e)}finally{refresh.disabled=false}});
 rebase.addEventListener('click',()=>{if(!f.isConnected||!reviewContextCurrent(context)||!reviewed)return;current=reviewed;baseRevision=reviewed.revision;reviewed=null;rebase.hidden=true;f.elements.namedItem('consent').checked=false;f.elements.namedItem('withdrawConsent').checked=false;options();persist();status.textContent='已采用刚核对的服务版本；请再次确认保存范围。'});
 f.addEventListener('submit',async e=>{e.preventDefault();if(busy||!f.isConnected||!reviewContextCurrent(context))return;const data=reviewProfileInput(f),fingerprint=JSON.stringify(data),button=f.querySelector('[type=submit]');busy=true;button.disabled=true;persist();try{await reviewFlush();if(!f.isConnected||!reviewContextCurrent(context))return;if(JSON.stringify(reviewProfileInput(f))!==fingerprint)throw Error('保存等待期间资料又有编辑，输入保留，请再次保存。');const r=await reviewKnowledgeRequest('/api/review-own-profile',{context,headers:{'If-Match':baseRevision},body:{...data,consent:f.elements.namedItem('consent').checked,withdrawConsent:f.elements.namedItem('withdrawConsent').checked}});if(!f.isConnected||!reviewContextCurrent(context))return;if(r.ownerId!==context.ownerId||JSON.stringify(r.profile)!==fingerprint)throw Error('个人资料保存回执不一致。');current=r;baseRevision=r.revision;showCurrent(r);reviewReadOwnProfileSummary(true);if(JSON.stringify(reviewProfileInput(f))===fingerprint){delete S.settings.profileDraft;save();status.textContent=data.visibility==='public'?'个人介绍已明确公开到服务。':'个人介绍已私人保存到服务。'}else{persist();status.textContent='提交时的资料已保存；之后的新输入保留，尚未提交。'}options()}catch(e){if(f.isConnected&&reviewContextCurrent(context))status.textContent=reviewOwnProfileError(e)}finally{busy=false;button.disabled=false}});
}
